function priceData(v){const full=Number(v.preco||0),cash=Number(v.cash_preco??full)||full,promo=v.promo_preco==null?null:Number(v.promo_preco),active=promo!=null&&promo>0&&promo<cash;return {full,cash,promo:active?promo:null,effectiveCash:active?promo:cash,card:active?Math.round(full*promo/cash):full}}
function promoPercent(v){const p=priceData(v);return p.promo?Math.round((1-p.promo/p.cash)*100):0}
function priceLabel(v){const p=priceData(v);return p.promo?`<strong>${money(p.promo)}</strong><div class="cash">${money(p.promo)} no PIX/dinheiro</div><div class="promotion">PROMOÇÃO · ${promoPercent(v)}% abaixo do preço padrão</div><div class="price-reference"><s>${money(p.full)}</s> no cartão: ${money(p.card)}</div>`:`<strong>${money(p.full)}</strong><div class="cash">${money(p.cash)} no PIX/dinheiro</div><div class="installments">Cartão: ${money(p.card)} em até 4x sem juros</div>`}
if(document.querySelector('#grid')){loadCatalogFromSupabase=async function(){try{const response=await fetch(ALMEIDA_SUPABASE_URL+'/rest/v1/products?active=eq.true&select=brand,name,subcategory,image_url,image_override_url,product_variants(name,price_cents,cash_price_cents,promo_price_cents,active)&order=name.asc',{headers:{apikey:ALMEIDA_SUPABASE_KEY,Authorization:'Bearer '+ALMEIDA_SUPABASE_KEY}});if(!response.ok)throw new Error('Catalog status '+response.status);const remote=await response.json();const normalized=remote.map((p,id)=>({id,marca:p.brand,nome:p.name,grupo:p.subcategory,imagem:p.image_override_url||localProductImage(p.brand,p.name,p.image_url),variacoes:(p.product_variants||[]).filter(v=>v.active).map(v=>({nome:v.name,preco:v.price_cents,cash_preco:v.cash_price_cents,promo_preco:v.promo_price_cents}))})).filter(p=>p.variacoes.length);if(normalized.length){produtos=normalized;render()}}catch(error){console.info('Catálogo local usado enquanto o banco não está disponível.',error)}};cardPrice=(p,variantIndex=0)=>priceLabel(p.variacoes[variantIndex]);openCart=()=>{const subtotal=cart.reduce((n,i)=>n+priceData(produtos[i.id].variacoes[i.vi]).full*i.qty,0),cashTotal=cart.reduce((n,i)=>n+priceData(produtos[i.id].variacoes[i.vi]).effectiveCash*i.qty,0),cardTotal=cart.reduce((n,i)=>n+priceData(produtos[i.id].variacoes[i.vi]).card*i.qty,0);$('#cart-items').innerHTML=cart.map((i,k)=>{const p=produtos[i.id],v=p.variacoes[i.vi],d=priceData(v);return `<div class="row"><div><strong>${p.nome}</strong><br><small>${v.nome} · ${i.qty} × ${money(d.full)}</small></div><button class="secondary" data-remove="${k}" aria-label="Remover">×</button></div>`}).join('');$('#checkout').innerHTML=cart.length?`<div class="totals">Preço cheio: <strong>${money(subtotal)}</strong><br>PIX/dinheiro: <strong>${money(cashTotal)}</strong><br>Cartão: <strong>${money(cardTotal)}</strong> em até 4x</div><label class="field">Pagamento<select id="payment"><option value="pix">PIX</option><option value="dinheiro">Dinheiro</option><option value="cartao">Cartão</option></select></label><label class="field">Recebimento<select id="fulfillment"><option value="retirada">Retirada na loja</option><option value="entrega">Entrega</option></select></label><div id="address-fields"></div><p class="notice">Pedido enviado pelo WhatsApp para confirmação. Nesta prévia, não há login, reserva de cashback ou pedido registrado no banco.</p><button class="primary" id="send">Enviar pedido pelo WhatsApp</button>`:'';$('#fulfillment')?.addEventListener('change',address);address();$('#send')?.addEventListener('click',send);$('#cart-dialog').showModal()};send=()=>{const payment=$('#payment').value,delivery=$('#fulfillment').value==='entrega',addr=$('#address')?.value.trim();if(delivery&&!addr){$('#address').focus();return}const totalFor=v=>{const d=priceData(v);return payment==='cartao'?d.card:d.effectiveCash},total=cart.reduce((n,i)=>n+totalFor(produtos[i.id].variacoes[i.vi])*i.qty,0),lines=cart.map(i=>{const p=produtos[i.id],v=p.variacoes[i.vi];return `${i.qty}× ${p.nome} — ${v.nome} — ${money(totalFor(v)*i.qty)}`});const msg=`Olá! Gostaria de fazer um pedido na Almeida Construções.\n\n${lines.join('\n')}\n\nPagamento: ${payment==='pix'?'PIX':payment==='dinheiro'?'Dinheiro':'Cartão (até 4x sem juros)'}\nTotal: ${money(total)}\nRecebimento: ${delivery?'Entrega':'Retirada na loja'}${delivery?'\nEndereço: '+addr:''}\n\nPedido sujeito à confirmação de disponibilidade dos produtos em estoque.`;window.open('https://wa.me/553220201300?text='+encodeURIComponent(msg),'_blank','noopener')};$('#cart-button').onclick=openCart;$('#cart-items').onclick=e=>{if(e.target.dataset.remove!==undefined){cart.splice(Number(e.target.dataset.remove),1);saveCart();$('#cart-dialog').close();render();openCart()}};loadCatalogFromSupabase()}
if(document.querySelector('#product-page-content')){loadProductFromSupabase=async function(){try{const response=await fetch(ALMEIDA_SUPABASE_URL+'/rest/v1/products?active=eq.true&select=brand,name,subcategory,description,image_url,image_override_url,source_url,product_variants(name,price_cents,cash_price_cents,promo_price_cents,active)&order=name.asc',{headers:{apikey:ALMEIDA_SUPABASE_KEY,Authorization:'Bearer '+ALMEIDA_SUPABASE_KEY}});if(!response.ok)throw new Error('Catalog status '+response.status);const remote=await response.json();const normalized=remote.map((p,id)=>({id,marca:p.brand,nome:p.name,grupo:p.subcategory,descricao:p.description,imagem:p.image_override_url||localProductImage(p.brand,p.name,p.image_url),fonte:p.source_url,variacoes:(p.product_variants||[]).filter(v=>v.active).map(v=>({nome:v.name,preco:v.price_cents,cash_preco:v.cash_price_cents,promo_preco:v.promo_price_cents}))})).filter(p=>p.variacoes.length);if(normalized.length){produtos=normalized;renderProduct()}}catch(error){console.info('Detalhes locais usados enquanto o banco não está disponível.',error)}};const originalProductRender=renderProduct;renderProduct=()=>{originalProductRender();const select=document.querySelector('#product-variant'),price=document.querySelector('#product-price');if(!select||!price)return;const update=()=>{const v=produtos[productId].variacoes[Number(select.value)],d=priceData(v);price.innerHTML=priceLabel(v)+`<small>Preço no cartão: ${money(d.card)} em até 4x sem juros</small>`;document.querySelector('.product-policy').textContent=v.promo_preco?'Promoção aplicada no PIX/dinheiro. No cartão, o valor é recalculado proporcionalmente.':'Preço à vista definido pela loja. No cartão, o valor cheio é mantido.'};select.onchange=update;update()};loadProductFromSupabase()}
